using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
namespace KianaPet {
 public sealed class HookEvent {public int Schema=2;public string SessionId,TurnId,Event,ToolId,TranscriptPath;public DateTime At;}
 public sealed class HookSession {public string Id,TranscriptPath;public DateTime LastEvent,LogUpdated,ClosedAt,OpenedAt;}
 public sealed class HookTurn {public string SessionId,Id;public bool Started,Ended,Interrupted;public DateTime Updated,FirstAt,StartedAt;public List<string> Waiting=new List<string>(),ToolsDone=new List<string>();}
 public sealed class HookCheckpoint {public int Schema=1;public List<HookSession> Sessions=new List<HookSession>();public List<HookTurn> Turns=new List<HookTurn>();}
 public static class HookJournal {
  public static readonly string[] Events={"SessionStart","UserPromptSubmit","PermissionRequest","PostToolUse","Stop","Interrupt","SessionEnd"};
  public static bool Id(string value){return Regex.IsMatch(value??"",@"^[A-Za-z0-9._:-]{1,160}$");}
  public static string Root{get{return Path.Combine(Store.Root,"connections","hooks");}}
  public static string Hash(string value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();}
  public static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152};}
  public static void Atomic(string path,string text){string directory=Path.GetDirectoryName(path);Directory.CreateDirectory(directory);string temp=Path.Combine(directory,"."+Guid.NewGuid().ToString("N")+".tmp");try{using(var file=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] data=new UTF8Encoding(false).GetBytes(text);file.Write(data,0,data.Length);file.Flush(true);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  public static string ValidTranscript(string path,string session,string home=null){try{if(!Id(session)||string.IsNullOrEmpty(path))return null;string root=Path.GetFullPath(home??Environment.GetEnvironmentVariable("CODEX_HOME")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex")).TrimEnd('\\')+"\\";string full=Path.GetFullPath(path);bool inside=full.StartsWith(root+"sessions\\",StringComparison.OrdinalIgnoreCase)||full.StartsWith(root+"archived_sessions\\",StringComparison.OrdinalIgnoreCase);return inside&&Path.GetExtension(full)==".jsonl"&&Path.GetFileNameWithoutExtension(full).EndsWith(session,StringComparison.OrdinalIgnoreCase)?full:null;}catch{return null;}}
  static string Value(Dictionary<string,object> data,string key){object value;return data.TryGetValue(key,out value)?Convert.ToString(value):null;}
  // The hook executable writes metadata durably before returning. No output and no decisions.
  public static int Receive(string root){try{var input=new StringBuilder();char[] buffer=new char[4096];int count;using(var reader=new StreamReader(Console.OpenStandardInput(),Encoding.UTF8)){while((count=reader.Read(buffer,0,buffer.Length))>0){if(input.Length+count>2097152)return 0;input.Append(buffer,0,count);}}var data=Json().DeserializeObject(input.ToString()) as Dictionary<string,object>;if(data==null)return 0;string session=Value(data,"session_id"),turn=Value(data,"turn_id"),kind=Value(data,"hook_event_name"),tool=Value(data,"tool_use_id");if(!Id(session)||!Events.Contains(kind))return 0;
   var e=new HookEvent{SessionId=session,TurnId=Id(turn)?turn:null,Event=kind,ToolId=Id(tool)?tool:null,At=DateTime.UtcNow,TranscriptPath=ValidTranscript(Value(data,"transcript_path"),session)};
   string path=Path.Combine(root,"events",Hash(session+"/"+e.TurnId+"/"+kind+"/"+e.ToolId)+".json");
   // Registration/lifecycle events can repeat after resume, so they retain distinct timestamps.
   if(e.TurnId==null)path=Path.Combine(root,"events",Guid.NewGuid().ToString("N")+".json");
   if(!File.Exists(path))Atomic(path,Json().Serialize(e));
  }catch{/* Advisory hooks never change the originating task's outcome. */}return 0;}
 }
 public sealed class HookBook {
  public readonly HookCheckpoint Data;public HookBook(HookCheckpoint data=null){Data=data??new HookCheckpoint();if(Data.Sessions==null)Data.Sessions=new List<HookSession>();if(Data.Turns==null)Data.Turns=new List<HookTurn>();}
  public void Apply(HookEvent e){if(e==null||!HookJournal.Id(e.SessionId)||!HookJournal.Events.Contains(e.Event)||e.At>DateTime.UtcNow.AddMinutes(5))return;var session=Data.Sessions.FirstOrDefault(s=>s.Id==e.SessionId);if(session==null){session=new HookSession{Id=e.SessionId};Data.Sessions.Add(session);}if(e.At>session.LastEvent)session.LastEvent=e.At;if(e.TranscriptPath!=null)session.TranscriptPath=e.TranscriptPath;if(e.Event=="SessionEnd"&&e.At>session.ClosedAt)session.ClosedAt=e.At;
   if(e.Event=="SessionStart"&&e.At>session.OpenedAt)session.OpenedAt=e.At;
   if(!HookJournal.Id(e.TurnId))return;var turn=Data.Turns.FirstOrDefault(t=>t.SessionId==e.SessionId&&t.Id==e.TurnId);if(turn==null){turn=new HookTurn{SessionId=e.SessionId,Id=e.TurnId};Data.Turns.Add(turn);}if(e.At>turn.Updated)turn.Updated=e.At;if(turn.FirstAt==DateTime.MinValue||e.At<turn.FirstAt)turn.FirstAt=e.At;
   if(e.Event=="UserPromptSubmit"){turn.Started=true;if(turn.StartedAt==DateTime.MinValue||e.At<turn.StartedAt)turn.StartedAt=e.At;}if(e.Event=="Stop")turn.Ended=true;if(e.Event=="Interrupt")turn.Interrupted=true;
   // Pair tool events by invocation ID; receipt order does not determine whether approval ended.
   if(e.Event=="PermissionRequest"&&!turn.Waiting.Contains(e.ToolId??"unknown"))turn.Waiting.Add(e.ToolId??"unknown");if(e.Event=="PostToolUse"&&e.ToolId!=null&&!turn.ToolsDone.Contains(e.ToolId))turn.ToolsDone.Add(e.ToolId);
  }
  public string State(HookTurn turn,DateTime now){var session=Data.Sessions.First(s=>s.Id==turn.SessionId);if(turn.Interrupted)return "interrupted";if(turn.Ended)return "review";if(session.ClosedAt>session.OpenedAt||now-(session.LogUpdated>turn.Updated?session.LogUpdated:turn.Updated)>TimeSpan.FromMinutes(5))return "unknown";if(turn.Waiting.Any(id=>!turn.ToolsDone.Contains(id)))return "waiting";return turn.Started?"running":"unknown";}
  public BridgeState Snapshot(DateTime now,bool appOpen){var next=new BridgeState{ConnectionSource="hooks",NotificationSource="hooks",AppOpen=appOpen,CanOpenTasks=false,MiniStatus="unused",MainStatus="unused",Code="hooks-waiting",Label="Hooks · 等待本地任务事件",Hint="首次使用需在 GPT 的 Hooks 设置中审核信任；此方式只提供本地任务状态。",At=now};if(!appOpen){next.Code="app-closed";next.Label="GPT 未运行 · Hooks 等待连接";return next;}if(Data.Sessions.Count==0)return next;
   next.Connected=true;next.Code="hooks-connected";next.LastSuccessAt=Data.Sessions.Max(s=>s.LastEvent);var recent=Data.Turns.Where(t=>now-t.Updated<TimeSpan.FromDays(1)).GroupBy(t=>t.SessionId).Select(g=>g.OrderByDescending(t=>t.StartedAt==DateTime.MinValue?t.FirstAt:t.StartedAt).First()).ToArray();int uncertain=recent.Count(t=>State(t,now)=="unknown");next.Notices=recent.Where(t=>State(t,now)!="interrupted").OrderByDescending(t=>t.Updated).Take(30).Select(t=>new BridgeNotice{Id=HookJournal.Hash(t.SessionId+"/"+t.Id).Substring(0,32),Title="本地任务 "+t.SessionId.Substring(0,Math.Min(8,t.SessionId.Length))+" · "+(State(t,now)=="review"?"回合已结束，待查看":State(t,now)=="unknown"?"状态待确认":State(t,now)=="waiting"?"等待处理":"处理中"),State=State(t,now),UpdatedAt=t.Updated}).ToArray();next.NotificationCount=next.Notices.Length;next.NotificationText=next.NotificationCount.ToString();next.CanNotifications=next.Notices.Length>0;next.State=new[]{"waiting","running","unknown","review"}.FirstOrDefault(s=>next.Notices.Any(n=>n.State==s))??"idle";next.Label="GPT 已联动（Hooks） · "+(uncertain>0?uncertain+" 项状态待确认":Bridge.Name(next.State));next.Hint="按任务和回合合并；结束/中断优先于晚到的运行事件。只回放状态事件，不保存聊天正文。"+(uncertain>0?" 缺少结束证据的任务保持待确认，不判为完成。":"");return next;
  }
 }
 public sealed class HookConnection {
  readonly string root,home;HookBook book;DateTime pathScan;readonly HashSet<string> seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);readonly Dictionary<string,DateTime> logTimes=new Dictionary<string,DateTime>();
  public HookConnection(string stateRoot=null,string codexHome=null){root=stateRoot??HookJournal.Root;home=codexHome;try{book=new HookBook(HookJournal.Json().Deserialize<HookCheckpoint>(File.ReadAllText(Path.Combine(root,"checkpoint.json"))));}catch{book=new HookBook();}}
  public BridgeState Read(DateTime now,bool appOpen){try{return ReadCore(now,appOpen);}catch{return new BridgeState{AppOpen=appOpen,ConnectionSource="hooks",CanOpenTasks=false,MiniStatus="unused",MainStatus="unused",Code="hooks-error",Label="Hooks 状态暂不可读 · 自动重试",Hint="请检查桌宠运行目录的读取权限；不会重启 GPT 或更改任务。",At=now};}}
  BridgeState ReadCore(DateTime now,bool appOpen){bool changed=false;string events=Path.Combine(root,"events");if(Directory.Exists(events))foreach(var file in Directory.EnumerateFiles(events,"*.json").Where(f=>!seen.Contains(f)).Take(1000)){try{if(new FileInfo(file).Length>16384)continue;var e=HookJournal.Json().Deserialize<HookEvent>(File.ReadAllText(file));e.TranscriptPath=HookJournal.ValidTranscript(e.TranscriptPath,e.SessionId,home);book.Apply(e);changed=true;}catch{}seen.Add(file);}
   if(now-pathScan>TimeSpan.FromSeconds(30)){pathScan=now;changed=ResolvePaths()||changed;}
   foreach(var session in book.Data.Sessions.Where(s=>s.TranscriptPath!=null).OrderByDescending(s=>s.LastEvent).Take(30)){string path=HookJournal.ValidTranscript(session.TranscriptPath,session.Id,home);if(path==null||!File.Exists(path))continue;try{DateTime updated=File.GetLastWriteTimeUtc(path),prior;if(logTimes.TryGetValue(path,out prior)&&prior==updated)continue;Recover(path,session);logTimes[path]=updated;session.LogUpdated=updated>now?now:updated;changed=true;}catch{}}
   if(changed){try{HookJournal.Atomic(Path.Combine(root,"checkpoint.json"),HookJournal.Json().Serialize(book.Data));}catch{}}
   return book.Snapshot(now,appOpen);
  }
  // Some desktop builds omit transcript_path. Only locate filenames for sessions
  // already registered through our hook journal; never inspect unrelated log contents.
  bool ResolvePaths(){bool changed=false;var missing=book.Data.Sessions.Where(s=>s.TranscriptPath==null||!File.Exists(s.TranscriptPath)).OrderByDescending(s=>s.LastEvent).Take(30).ToArray();if(missing.Length==0)return false;string codex=home??HookSetup.Home;foreach(string folder in new[]{"sessions","archived_sessions"}){string directory=Path.Combine(codex,folder);if(!Directory.Exists(directory))continue;try{foreach(string file in Directory.EnumerateFiles(directory,"*.jsonl",SearchOption.AllDirectories).Take(10000)){string stem=Path.GetFileNameWithoutExtension(file);foreach(var session in missing.Where(s=>s.TranscriptPath==null||!File.Exists(s.TranscriptPath))){if(!stem.EndsWith("-"+session.Id,StringComparison.OrdinalIgnoreCase))continue;string valid=HookJournal.ValidTranscript(file,session.Id,home);if(valid!=null){session.TranscriptPath=valid;changed=true;}}}}catch{}}return changed;}
  void Recover(string path,HookSession session){using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){long start=Math.Max(0,file.Length-2097152);file.Position=start;byte[] bytes=new byte[file.Length-start];int read=0,n;while(read<bytes.Length&&(n=file.Read(bytes,read,bytes.Length-read))>0)read+=n;int begin=0;if(start>0){while(begin<read&&bytes[begin]!=10)begin++;begin++;}for(int i=begin;i<read;i++)if(bytes[i]==10){string line=Encoding.UTF8.GetString(bytes,begin,i-begin);begin=i+1;try{var item=HookJournal.Json().DeserializeObject(line) as Dictionary<string,object>;if(item==null||Convert.ToString(MusicBridge.Get(item,"type"))!="event_msg")continue;var payload=MusicBridge.Get(item,"payload") as Dictionary<string,object>;if(payload==null)continue;string type=MusicBridge.Str(payload,"type"),kind=type=="task_started"?"UserPromptSubmit":type=="task_complete"?"Stop":type=="turn_aborted"?"Interrupt":null;if(kind==null)continue;DateTime at;if(!DateTime.TryParse(MusicBridge.Str(item,"timestamp"),CultureInfo.InvariantCulture,DateTimeStyles.AdjustToUniversal|DateTimeStyles.AssumeUniversal,out at))continue;book.Apply(new HookEvent{SessionId=session.Id,TurnId=MusicBridge.Str(payload,"turn_id"),Event=kind,At=at});}catch{}}}}
 }
}
